{"code": "import os
# List materials directory contents
materials_dir = './materials'
if os.path.exists(materials_dir):
    files = os.listdir(materials_dir)
    for f in files:
        full_path = os.path.join(materials_dir, f)
        size = os.path.getsize(full_path)
        print(f"{f} ({size} bytes)")
else:
    print("materials/ directory not found, checking current dir")
    for f in os.listdir('.'):
        print(f)"}

